import {applyDaily,dailyView} from './daily-core.mjs';
import {applyPet,petView,PetError} from './pet-core.mjs';
import {parkingChannelAccess} from './parking-membership.mjs';
import {parkingView,applyParking,ParkingError} from './parking-course.mjs';
import {fullVersionRequired} from './payment-core.mjs';
class Rejected extends Error { constructor(message,status=400){super(message);this.status=status} }
const fail=(message,status)=>{throw new Rejected(message,status)};
const clean=(s,max=400)=>typeof s==='string'?s.trim().slice(0,max):'';
function calendar(now=new Date()) {
 const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);
 const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);
 return {day,week:d.toISOString().slice(0,10)};
}
function fresh(){return {schema:1,career:{done:[],active:null,awards:[],equippedAward:null,week:{},lastDriveDay:null},garage:{wallet:150,owned:['paint:0','rims:0','neon:0'],equipped:{paint:0,rims:0,neon:0}},modes:{dragWins:0,dragBest:null,driftWins:0},circuit:{routes:[],selected:null,equipped:null},claims:{},drag:null,drift:null};}
function award(s,key,amount,drive,now){
 if(s.claims[key])return 0;
 const {day,week}=calendar(now),w=s.career.week[week]||{rep:0,drives:0};
 if(drive&&s.career.lastDriveDay===day)fail('Сегодня поездка уже зачтена. Следующая — в другой день.',409);
 const gain=Math.max(0,Math.min(amount,80-w.rep,drive&&w.drives>=3?0:80));
 s.career.week[week]={rep:w.rep+gain,drives:w.drives+(drive?1:0)};
 if(drive)s.career.lastDriveDay=day;
 s.garage.wallet+=gain;s.claims[key]={at:now.toISOString(),gain};return gain;
}
function route(s,id){return s.circuit.routes.find(r=>r.id===id)||fail('Маршрут не найден',404)}
function preparePlan(p){
 if(!p||typeof p!=='object')fail('Нужен план маршрута');
 if(JSON.stringify(p).length>150000)fail('План слишком большой',413);
 const points=p.points;
 if(!Array.isArray(points)||points.length>40)fail('Слишком много точек');
 for(const point of points){
  if(!['start','end','via','hazard','parking','backup'].includes(point.kind)||!Number.isFinite(point.lat)||!Number.isFinite(point.lng)||Math.abs(point.lat)>90||Math.abs(point.lng)>180)fail('Некорректная точка');
 }
 return structuredClone(p);
}
function engine(catalog){
 const questions=new Map(catalog.questions.map(q=>[q.id,q]));
 return function apply(source,event,a={},now=new Date(),random=Math.random){
 const s=structuredClone(source);let reward=0,feedback=null;
 switch(event){
 case 'road.start': case 'road.answer': case 'road.next': {
  const map=catalog.roadStories;
  if(!map)fail('Истории пока недоступны',404);
  s.roadStories??={version:1,completed:{},run:null};
  const stories=s.roadStories;
  if(event==='road.start'){
   const trip=map.routes.find(r=>r.id===a.trip);
   if(!trip)fail('Поездка не найдена',404);
   if(trip.unlock_after&&!Object.hasOwn(stories.completed,trip.unlock_after))fail('Сначала заверши предыдущую поездку',409);
   const required=({r04:10,r05:10,r06:25,r07:25,p01:25,p02:50,p03:50,p04:50,x01:80})[trip.id]||0;
   const totalRep=Object.values(s.career.week||{}).reduce((sum,w)=>sum+Math.max(0,Number(w.rep)||0),0);
   if(!Object.hasOwn(stories.completed,trip.id)&&totalRep<required)fail('Нужен новый игровой уровень: '+required+' REP за всё время. Сейчас '+totalRep+' REP.',409);
   stories.run={tutorial:trip.id==='r01'&&a.tutorial===true&&!Object.hasOwn(stories.completed,trip.id),routeId:trip.id,index:0,status:'question',selected:null,log:[],presentationVersion:a.presentationVersion===3?3:a.presentationVersion===2?2:1,errorLimit:a.presentationVersion===3?(trip.task_ids.length>=10?2:trip.task_ids.length>=6?1:0):0,errors:0,attemptId:crypto.randomUUID()};break;
  }
  const run=stories.run,trip=map.routes.find(r=>r.id===run?.routeId);
  if(!run||!trip||a.attemptId!==run.attemptId||a.index!==run.index)fail('Попытка изменилась. Начни поездку заново.',409);
  if(event==='road.answer'){
   if(run.status!=='question'&&run.status!=='practice')fail('Ответ уже обработан',409);
   const task=map.tasks.find(t=>t.id===trip.task_ids[run.index]);
   if(!Number.isInteger(a.answer)||a.answer<1||a.answer>task.optionCount)fail('Выбери вариант ответа');
   const right=a.answer===task.correct;run.selected=a.answer;
   if(!right&&(run.tutorial||task.nonDriving)&&run.presentationVersion>=2){
    run.status='practice';run.practiceMistakes??=[];run.practiceMistakes.push({id:task.id,number:a.answer});feedback={right:false,practice:true};break;
   }
   run.log.push({id:task.id,number:a.answer,correct:right});if(!right)run.errors=(run.errors||0)+1;
   const limit=run.errorLimit||0;run.status=right?'feedback':run.errors<=limit?'review':'failed';feedback={right,errors:run.errors||0,errorLimit:limit,canContinue:run.status==='review'};break;
  }
  if(!['feedback','review'].includes(run.status))fail('Поездка прервана или ответ ещё не выбран',409);
  run.index++;run.selected=null;
  if(run.index===trip.task_ids.length){
   run.status='complete';
   if(!Object.hasOwn(stories.completed,trip.id)){
    reward=award(s,'road-story:'+trip.id,5,false,now);stories.completed[trip.id]={at:now.toISOString()};s.modes['road-story-'+trip.id]=true;
   }
  }else run.status='question';
  break;
 }

 case 'career.select': case 'career.complete': {
  const m=catalog.catalog.find(m=>m.id===a.id);if(!m)fail('Задание не найдено',404);
  if(m.chapter!==undefined&&m.step>0&&!s.career.done.includes(`c${m.chapter}s${m.step-1}`))fail('Сначала предыдущий этап',409);
  if(event==='career.select'){s.career.active=m.id;break}
  if(s.career.done.includes(m.id))break;
  if(m.type==='quiz'){if(a.answer!==catalog.scenarios[m.quiz][3])fail('Пересмотри решение');}
  else if(a.confirmed!==true)fail('Подтверди завершение задания вне движения');
  reward=award(s,'career:'+m.id,m.type==='drive'?(clean(a.note)?25:20):5,m.type==='drive',now);
  if(m.type==='drive'){s.career.practiceNotes??={};s.career.practiceNotes[m.id]={at:now.toISOString(),note:clean(a.note,500)};}
  s.career.done.push(m.id);s.career.active=null;
  if(m.chapter!==undefined&&catalog.catalog.filter(x=>x.chapter===m.chapter).every(x=>s.career.done.includes(x.id))&&!s.career.awards.includes(m.chapter))s.career.awards.push(m.chapter);
  break;
 }
 case 'garage.equip': {
  if(!Object.hasOwn(catalog.parts,a.category)||!Number.isInteger(a.index)||!catalog.parts[a.category][a.index])fail('Деталь не найдена');
  const key=a.category+':'+a.index,cost=catalog.parts[a.category][a.index][1];
  if(!s.garage.owned.includes(key)){if(s.garage.wallet<cost)fail('Недостаточно CR',409);s.garage.wallet-=cost;s.garage.owned.push(key)}
  s.garage.equipped[a.category]=a.index;break;
 }
 case 'garage.award': {
  if(!s.career.awards.includes(a.chapter))fail('Награда ещё закрыта',409);s.career.equippedAward=a.chapter;break;
 }
 case 'drag.start': {
  if(s.drag&&!s.drag.finished&&now.getTime()-s.drag.started<1200)fail('Подожди секунду перед стартом',429);
  const ids=[...questions.keys()];for(let i=ids.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}
  s.drag={ids:ids.slice(0,a.questionCount===10?10:3),index:0,errors:0,started:now.getTime(),finished:false};break;
 }
 case 'drag.answer': {
  const d=s.drag;if(!d||d.finished)fail('Сначала начни заезд',409);
  if(d.index!==a.index)fail('Этот вопрос уже обработан',409);
  if(now.getTime()-d.started>3600000)fail('Заезд истёк, начни заново',409);
  const q=questions.get(d.ids[d.index]);
  if(!Number.isInteger(a.answer)||a.answer<0||a.answer>=q.a.length)fail('Выбери вариант ответа');
  const right=a.answer===q.ok;feedback={right,explanation:q.ex||'',correct:q.ok};
  if(!right){d.errors++;break}
  d.index++;if(d.index===d.ids.length){d.finished=true;d.finishedAt=now.getTime();s.modes.dragWins++;reward=award(s,'mode-drag',5,false,now);
   s.modes['mode-drag']=true;const seconds=(now.getTime()-d.started)/1000;
   const bestKey=d.ids.length===10?'dragBest10':'dragBest';
   if(!d.errors&&(s.modes[bestKey]==null||seconds<s.modes[bestKey]))s.modes[bestKey]=seconds;
  }break;
 }
 case 'drift.start': {
  if(!(a.trip==='district'||Object.hasOwn(catalog.newTripDefinitions,a.trip)))fail('Поездка не найдена');
  s.drift={trip:a.trip,node:a.trip==='district'?'approach':'entry',log:[],errors:0,finished:false};break;
 }
 case 'drift.choose': {
  const d=s.drift;if(d?.failed)fail('Попытка завершена. Начни маршрут заново.',409);
  if(!d||d.finished)fail('Сначала выбери поездку',409);
  if(a.node!==d.node)fail('Сцена уже изменилась',409);
  const node=d.trip==='district'?catalog.districtNodes[d.node]:catalog.newTripDefinitions[d.trip].nodes[d.node];
  const options=node.actions||node.options,o=options[a.choice];if(!o)fail('Выбери действие');
  const next=o.next??(Array.isArray(o)?o[1]:null),text=o.text||o[0];
  feedback={text,result:o.result||o[2],detail:o.detail||o[3],right:!!next};
  if(!next){d.errors++;if(d.trip==='shopping')d.failed=true;break}
  d.log.push({node:d.node,choice:a.choice,text,result:feedback.result});
  if(next==='finish'){d.finished=true;const key=d.trip==='district'?'mode-drift-district':'trip-'+d.trip;reward=award(s,key,5,false,now);s.modes[key]=true}else d.node=next;
  break;
 }
 case 'circuit.create': {
  const title=clean(a.title,60);if(!title)fail('Назови маршрут');if(s.circuit.routes.length>=8)fail('Можно сохранить до восьми маршрутов');
  const id=crypto.randomUUID();s.circuit.routes.push({id,title,duration:clean(a.duration,30),focus:clean(a.focus,40),prepared:false,laps:[],practices:[],created:calendar(now).day});s.circuit.selected=id;break;
 }
 case 'circuit.select': route(s,a.id);s.circuit.selected=a.id;break;
 case 'circuit.plan': {
  const r=route(s,a.id);if(r.laps.length)fail('Путь закреплён после первого круга',409);
  r.plan=preparePlan(a.plan);
  if(a.complete){
   const kinds=r.plan.points.map(p=>p.kind);
   if(!['start','end','parking','backup'].every(k=>kinds.includes(k))||!['route','parking','ready'].every(k=>r.plan.checks?.[k]===true))fail('Подтверди путь, две парковки и готовность');
   const chosen=r.plan.routes?.[r.plan.selectedRoute];if(chosen?.geometry?.type!=='LineString'||chosen.geometry.coordinates.length<2)fail('Сначала построй путь по дорогам');
   if(!r.prepared){r.prepared=true;r.preparedDay=calendar(now).day;r.prepareReward=reward=award(s,'prepare:'+r.id,5,false,now)}
  }else r.prepared=false;
  break;
 }
 case 'circuit.lap': {
  const r=route(s,a.id);if(!r.prepared||r.laps.length>=3)fail('Маршрут не готов или уже завершён',409);
  const day=calendar(now).day;
  if(!['complete','partial','postpone'].includes(a.outcome))fail('Выбери результат');
  if(a.outcome==='postpone'){r.practices.push({day,outcome:a.outcome});break}
  if(a.stopped!==true||!['solo','instructor','companion'].includes(a.support)||!Number.isInteger(a.confidence)||a.confidence<1||a.confidence>5)fail('Подтверди остановку и заполни разбор');
  const rec={day,outcome:a.outcome,support:a.support,confidence:a.confidence,success:clean(a.success),next:clean(a.next)};
  if(a.outcome==='partial'||r.laps.length===2&&a.support!=='solo'){r.practices.push(rec);break}
  if(r.laps.some(x=>x.day===day))fail('Следующий круг — в другой день',409);
  rec.reviewed=!!rec.success&&!!rec.next;rec.reward=reward=award(s,'lap:'+r.id+':'+r.laps.length,rec.reviewed?25:20,true,now);r.laps.push(rec);break;
 }
 case 'circuit.badge': {
  const r=route(s,a.id);if(r.laps.length!==3)fail('Пройди три круга',409);s.circuit.equipped=r.id;break;
 }
 default: fail('Неизвестное действие',404);
 }
 if(s.circuit.routes.some(r=>r.practices.length>100))fail('Журнал заполнен');
 return {state:s,reward,feedback};
 };
}
function publicQuestion(state,catalog){
 const d=state.drag;if(!d||d.finished)return null;
 const q=catalog.questions.find(q=>q.id===d.ids[d.index]);
 const {ok,ex,...view}=q;return view;
}
function privateView(s,catalog){const v=structuredClone(s);v.pet=petView(v.pet);v.daily=dailyView(s);if(v.drag){v.drag.total=v.drag.ids.length;delete v.drag.ids;v.drag.question=publicQuestion(s,catalog)}return v;}

// Telegram third-party Ed25519 validation; no bot token required.
const PROD_KEY='e7bf03a2fa4602af4580703d88dda5bb59f32ed8b02a56c187fe7d34caed242d';
const bytes=hex=>Uint8Array.from(hex.match(/../g),x=>parseInt(x,16));
async function verifyTelegram(raw,botId,{now=Date.now(),publicKey=PROD_KEY}={}){
 if(typeof raw!=='string'||raw.length>16384||!/^\d{5,16}$/.test(String(botId)))return null;
 try{
 const p=new URLSearchParams(raw),keys=[...p.keys()];if(new Set(keys).size!==keys.length)return null;
 const date=Number(p.get('auth_date'));if(!Number.isSafeInteger(date)||date<now/1000-86400||date>now/1000+60)return null;
 const signature=p.get('signature');if(!signature||!/^[\w-]{85,88}={0,2}$/.test(signature))return null;
 const data=String(botId)+':WebAppData\n'+[...p].filter(([k])=>k!=='hash'&&k!=='signature').sort(([a],[b])=>a<b?-1:a>b?1:0).map(([k,v])=>k+'='+v).join('\n');
 const key=await crypto.subtle.importKey('raw',bytes(publicKey),{name:'Ed25519'},false,['verify']);
 const binary=atob(signature.replaceAll('-','+').replaceAll('_','/').padEnd(Math.ceil(signature.length/4)*4,'='));
 const valid=await crypto.subtle.verify('Ed25519',key,Uint8Array.from(binary,c=>c.charCodeAt(0)),new TextEncoder().encode(data));
 if(!valid)return null;
 const user=JSON.parse(p.get('user')||'null');if(!user||!Number.isSafeInteger(user.id)||user.id<=0||user.is_bot)return null;
 return 'tg:'+user.id;
 }catch{return null}
}
async function telegramIdentity(request,env){
 const header=request.headers.get('Authorization')||'';
 return header.startsWith('tma ')?verifyTelegram(header.slice(4),env.TELEGRAM_BOT_ID):null;
}

