async function rpc(name,body){
 const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');const key=keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');if(!key)throw new Error('Missing database credentials');
 const headers={'Content-Type':'application/json',apikey:key};if(key.startsWith('eyJ'))headers.Authorization='Bearer '+key;
 const response=await fetch(Deno.env.get('SUPABASE_URL')+'/rest/v1/rpc/'+name,{method:'POST',headers,body:JSON.stringify(body)});
 if(!response.ok){console.error('DATABASE_RPC_FAILED',name,response.status);throw new Error('Database unavailable')}
 return response.json();
}
function completedGameTask(before,after,event,data={}){
 if(event==='career.complete')return !before.career.done.includes(data.id)&&after.career.done.includes(data.id);
 if(event==='road.next')return ['feedback','review'].includes(before.roadStories?.run?.status)&&after.roadStories?.run?.status==='complete';
 if(event==='drag.answer')return !!after.drag?.finished&&!before.drag?.finished;
 if(event==='drift.choose')return !!after.drift?.finished&&!before.drift?.finished;
 if(event==='circuit.lap'){const a=before.circuit.routes.find(r=>r.id===data.id),b=after.circuit.routes.find(r=>r.id===data.id);return !!a&&!!b&&b.laps.length>a.laps.length}
 if(event==='circuit.plan'){const a=before.circuit.routes.find(r=>r.id===data.id),b=after.circuit.routes.find(r=>r.id===data.id);return !!a&&!!b&&!a.prepared&&b.prepared}
 return false;
}

